content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-22-express-430

=== 用户原始指令 (query.txt) ===
整个能打勾的物流清单吧，有距离数字，点确认收货，读天气看签收

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个能打勾的物流清单吧，有距离数字，点确认收货，读天气看签收",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "ViewCalendarEvent",
        "params": {
          "entityId": "express_confirm_430"
        }
      }
    },
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModel": {
    "value": {
      "summary": {
        "title": "物流清单",
        "statusText": "可签收",
        "distanceText": "距驿站 0.8km",
        "confirmLabel": "确认收货"
      },
      "parcels": [
        {
          "label": "到达驿站",
          "done": true
        },
        {
          "label": "天气适合签收",
          "done": true
        },
        {
          "label": "待确认收货",
          "done": false
        }
      ],
      "assets": {
        "weatherIcon": "resources/base/media/icon_weather1.png"
      },
      "data": {
        "weather": {
          "location": {},
          "current": {
            "temperatureText": "--",
            "condition": "查询中",
            "airQuality": ""
          },
          "daily": [],
          "updatedAt": ""
        }
      },
      "state": {
        "loading": true
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "weatherIcon",
      "src": "resources/base/media/icon_weather1.png",
      "use": "weather glyph for delivery signing reference",
      "description": "天气雨伞图标，可用于表达签收前查看天气。",
      "bindTo": "/assets/weatherIcon",
      "static": true
    }
  ]
}

